/**
 * components/PredictionCard.js
 * Hero card — ticker, price, direction badge, confidence bar,
 * mini trajectory chart
 */

import React, { useState, useEffect } from 'react';
import {
  AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer,
} from 'recharts';
import './PredictionCard.css';

/* Build a smooth simulated price path current → predicted */
function buildChart(cp, pp) {
  const labels = ['T-4','T-3','T-2','T-1','Now','T+1','T+2','T+3','T+4','T+5'];
  const diff   = pp - cp;
  return labels.map((t, i) => {
    if (i === 4) return { t, v: +cp.toFixed(2) };
    if (i === 9) return { t, v: +pp.toFixed(2) };
    const noise = (Math.random() - 0.5) * Math.abs(diff) * 0.28;
    const base  = i < 5
      ? cp + diff * 0.12 * i + (Math.random() - 0.5) * Math.abs(diff) * 0.18
      : cp + diff * (0.55 + (i - 5) * 0.09) + noise;
    return { t, v: +Math.max(cp * 0.94, Math.min(cp * 1.06, base)).toFixed(2) };
  });
}

export default function PredictionCard({ prediction, stockName }) {
  const [confW, setConfW] = useState(0);

  useEffect(() => {
    setConfW(0);
    const t = setTimeout(() => setConfW(prediction.confidence * 100), 180);
    return () => clearTimeout(t);
  }, [prediction]);

  const isUp     = prediction.direction?.includes('UP');
  const regime   = prediction.regime?.regime_name || prediction.regime?.name || 'Unknown';
  const chartData = buildChart(prediction.current_price, prediction.predicted_price);

  return (
    <div className="pred-hero">
      {/* accent line */}
      <div className="ph-accent" />

      {/* TOP ROW */}
      <div className="ph-top">
        <div>
          <div className="ph-ticker">{prediction.ticker}</div>
          <div className="ph-co">{stockName}</div>
          <div className="ph-time">
            {new Date(prediction.timestamp).toLocaleString('en-US',{
              month:'short', day:'numeric', hour:'2-digit', minute:'2-digit',
            })}
          </div>
        </div>
        <div className={`dir-badge ${isUp ? 'dir-up' : 'dir-dn'}`}>
          <span>{isUp ? '↑' : '↓'}</span>
          <span>{isUp ? 'BULLISH' : 'BEARISH'}</span>
        </div>
      </div>

      {/* PRICE GRID */}
      <div className="ph-prices">
        <div className="px-cell">
          <div className="px-lbl">Current Price</div>
          <div className="px-val pv-cur">${prediction.current_price.toFixed(2)}</div>
        </div>
        <div className="px-cell">
          <div className="px-lbl">Predicted Price</div>
          <div className="px-val pv-pred">${prediction.predicted_price.toFixed(2)}</div>
        </div>
        <div className="px-cell">
          <div className="px-lbl">Expected Change</div>
          <div className={`px-val ${isUp ? 'pv-up' : 'pv-dn'}`}>
            {prediction.change_percent >= 0 ? '+' : ''}
            {prediction.change_percent.toFixed(2)}%
          </div>
        </div>
        <div className="px-cell">
          <div className="px-lbl">Market Regime</div>
          <div className={`px-val regime-${regime.toLowerCase()}`}>{regime}</div>
        </div>
      </div>

      {/* CONFIDENCE */}
      <div className="conf-row">
        <div className="conf-hdr">
          <span className="conf-lbl">Model Confidence</span>
          <span className="conf-num">{(prediction.confidence * 100).toFixed(1)}%</span>
        </div>
        <div className="conf-track">
          <div className="conf-fill" style={{ width: `${confW}%` }} />
        </div>
      </div>

      {/* MINI CHART */}
      <div className="mini-chart">
        <div className="mc-label">Predicted Trajectory</div>
        <ResponsiveContainer width="100%" height={130}>
          <AreaChart data={chartData} margin={{ top:6, right:4, bottom:0, left:0 }}>
            <defs>
              <linearGradient id="aGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%"  stopColor={isUp ? '#00e87a' : '#ff3b6b'} stopOpacity={0.25} />
                <stop offset="95%" stopColor={isUp ? '#00e87a' : '#ff3b6b'} stopOpacity={0} />
              </linearGradient>
            </defs>
            <XAxis dataKey="t"
              tick={{ fill:'#3a4558', fontSize:9, fontFamily:'JetBrains Mono' }}
              axisLine={false} tickLine={false} />
            <YAxis domain={['auto','auto']}
              tick={{ fill:'#3a4558', fontSize:9, fontFamily:'JetBrains Mono' }}
              axisLine={false} tickLine={false} width={52}
              tickFormatter={v => `$${v.toFixed(0)}`} />
            <Tooltip
              contentStyle={{ background:'#0b0f1a', border:'1px solid rgba(0,210,255,.2)', borderRadius:8, fontFamily:'JetBrains Mono', fontSize:11 }}
              formatter={v => [`$${v.toFixed(2)}`, 'Price']}
              labelStyle={{ color:'#5a6a82' }} />
            <Area type="monotone" dataKey="v"
              stroke={isUp ? '#00e87a' : '#ff3b6b'}
              strokeWidth={2} fill="url(#aGrad)" />
          </AreaChart>
        </ResponsiveContainer>
        <div className="mc-note">Simulated path · Current → T+5 predicted endpoint</div>
      </div>
    </div>
  );
}
